            case .value(let value): try container.encode(value, forKey: .changed)
            }
            try container.encode(generation, forKey: .generation)
            try container.encode(index, forKey: .index)
            try container.encode(key, forKey: .key)
            try container.encode(registryId, forKey: .registryId)
            try container.encode(replayed, forKey: .replayed)
            try container.encode(workspace, forKey: .workspace)
            try container.encode(workspaceRevision, forKey: .workspaceRevision)
        }
    }

    struct ZoomPaneResult: Codable, Sendable, Equatable {
        let pane: CloudTuiGenerated.Id
        let zoomed: Bool
        let zoomedPane: CloudTuiGenerated.Id?

        init(pane: CloudTuiGenerated.Id, zoomed: Bool, zoomedPane: CloudTuiGenerated.Id?) {
            self.pane = pane
            self.zoomed = zoomed
            self.zoomedPane = zoomedPane
        }

        enum CodingKeys: String, CodingKey {
            case pane = "pane"
            case zoomed = "zoomed"
            case zoomedPane = "zoomed_pane"
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            self.pane = try container.decode(CloudTuiGenerated.Id.self, forKey: .pane)
            self.zoomed = try container.decode(Bool.self, forKey: .zoomed)
            guard container.contains(.zoomedPane) else { throw CodecError.missingRequiredField("zoomed_pane") }
            self.zoomedPane = try container.decodeIfPresent(CloudTuiGenerated.Id.self, forKey: .zoomedPane)
        }

        func encode(to encoder: Encoder) throws {
            var container = encoder.container(keyedBy: CodingKeys.self)
            try container.encode(pane, forKey: .pane)
            try container.encode(zoomed, forKey: .zoomed)
            try container.encode(zoomedPane, forKey: .zoomedPane)
        }
    }

